<script lang="ts">
  import {onDestroy} from 'svelte';
  import Mascot from './Mascot.svelte';
  import type {AgentState} from '../types';
  export let entering=false;
  export let state:AgentState='idle';export let motion=true;export let visible=true;
  let x=0,y=0,boop=false,over=false,release:ReturnType<typeof setTimeout>|undefined;
  const particles=Array.from({length:10},(_,i)=>({x:50+44*Math.cos(i*.628),y:49+36*Math.sin(i*.628),delay:-i*.71,size:i%3===0?3:2}));
  $: alive=motion&&visible;
  $: busy=state==='working'||state==='thinking';
  function follow(e:PointerEvent){if(!alive||entering)return;const r=e.currentTarget as HTMLButtonElement,b=r.getBoundingClientRect();x=((e.clientX-b.left)/b.width-.5)*12;y=((e.clientY-b.top)/b.height-.5)*9;over=true;}
  function leave(){x=0;y=0;over=false;}
  function greet(){if(!alive||entering)return;clearTimeout(release);boop=true;release=setTimeout(()=>boop=false,850);}
  onDestroy(()=>clearTimeout(release));
</script>
<button class="stage" class:entering class:busy class:boop class:over class:still={!alive} data-mascot-stage data-phase={state} style={`--look-x:${alive?x:0}px;--look-y:${alive?y:0}px;--tilt:${alive?x*.65:0}deg`} onpointermove={follow} onpointerleave={leave} onblur={leave} onclick={greet} title="Fais coucou à Axon" aria-label="Faire coucou à Axon">
 <span class="bloom" aria-hidden="true"></span><span class="aura secondary" aria-hidden="true"></span>
 <span class="orbital" aria-hidden="true"><i></i></span><span class="orbital second" aria-hidden="true"><i></i></span>
 {#each particles as particle,i (i)}<span class="mote" aria-hidden="true" style={`left:${particle.x}%;top:${particle.y}%;--delay:${particle.delay}s;--size:${particle.size}px`}></span>{/each}
 <span class="floor" aria-hidden="true"></span>
 <span class="follow"><span class="float"><span class="greet"><Mascot {state} motion={alive} {visible} {entering}/></span></span></span>
 <span class="hello" aria-hidden="true">coucou ! <i>✦</i></span>
 <span class="spark a" aria-hidden="true">✧</span><span class="spark b" aria-hidden="true">✧</span>
</button>
<style>
.entering .float{animation:none}.entering .bloom,.entering .aura,.entering .orbital,.entering .mote,.entering .floor,.entering .hello,.entering .spark{visibility:hidden}.entering .follow{transform:none;transition:none}.entering .bloom{background:radial-gradient(ellipse,#ffbd514a,transparent 72%)}

.stage{position:relative;display:block;width:100%;height:100%;border:0;border-radius:50%;isolation:isolate;cursor:pointer;-webkit-tap-highlight-color:transparent}.stage:focus-visible{outline:1px solid #ffca6980;outline-offset:-10px}.bloom{position:absolute;inset:12%;border-radius:50%;background:radial-gradient(ellipse,#ffb02c2b 0%,#ff9b1711 39%,transparent 70%);transform:scale(1);animation:halo 6s ease-in-out infinite}.aura{position:absolute;left:26%;right:15%;top:20%;bottom:20%;border-radius:50%;background:radial-gradient(ellipse,#9f76ed13,transparent 72%);transform:translate(20px,-10px)}.orbital{position:absolute;width:90%;height:40%;left:5%;top:36%;border:1px solid #ffc66816;border-radius:50%;transform:rotate(-24deg);pointer-events:none}.orbital i{position:absolute;top:13%;left:11%;width:4px;height:4px;border-radius:50%;background:#ffe0a4;box-shadow:0 0 8px #ffad4888;animation:beacon 3.8s ease-in-out infinite}.orbital.second{width:75%;height:67%;left:12%;top:14%;border-color:#e6c6ff0b;transform:rotate(27deg)}.second i{top:85%;left:80%;width:3px;height:3px;background:#bc9eef;box-shadow:0 0 7px #d4a4ff88;animation-delay:-1.4s}.mote{position:absolute;width:var(--size);height:var(--size);border-radius:50%;background:#ffdb99;box-shadow:0 0 5px #ffcf5655;animation:mote 4.6s var(--delay) ease-in-out infinite;pointer-events:none;opacity:.5}.floor{position:absolute;left:27%;right:27%;bottom:11%;height:8px;border-radius:50%;background:radial-gradient(ellipse,#ffa92c30,transparent 72%);animation:floor 5.2s ease-in-out infinite}.follow{position:absolute;inset:4%;transform:translate(var(--look-x),var(--look-y)) rotate(var(--tilt));transition:transform 240ms cubic-bezier(.2,.8,.2,1);pointer-events:none}.float,.greet{display:block;width:100%;height:100%}.float{animation:levitate 5.2s ease-in-out infinite}.greet{transform-origin:50% 70%}.boop .greet{animation:greet 850ms cubic-bezier(.22,.8,.26,1)}.hello{position:absolute;top:3%;right:3%;font:9px var(--mono);color:#ffe1a2;background:#31271ebd;border:1px solid #ffdb9940;border-radius:20px;padding:5px 9px;opacity:0;transform:translateY(8px) rotate(8deg);transition:opacity .18s,transform .3s;pointer-events:none}.boop .hello{opacity:1;transform:translateY(0) rotate(8deg)}.hello i{font-style:normal;margin-left:3px}.spark{position:absolute;font-size:18px;color:#ffde9b;opacity:0;pointer-events:none;transition:opacity .2s,transform .4s}.spark.a{left:10%;top:22%;transform:scale(.5)}.spark.b{right:11%;top:58%;transform:scale(.5)}.boop .spark{opacity:.8;transform:scale(1.15) rotate(20deg)}.over .bloom{background:radial-gradient(ellipse,#ffc25838 0%,#ff9b1714 40%,transparent 72%)}.busy .orbital{border-color:#ffc6682b}.busy .mote{animation-duration:2.8s}.busy .bloom{animation-duration:3s}.stage[data-phase="finished"] .bloom{background:radial-gradient(ellipse,#b1ffbb23,transparent 70%)}.stage[data-phase="waiting"] .bloom{background:radial-gradient(ellipse,#ffd86730,transparent 70%)}.stage[data-phase="sleeping"]{opacity:.72}.still *{animation:none!important;transition:none!important}.still .follow{transform:none}.still .hello,.still .spark{opacity:0}
@keyframes levitate{0%,100%{transform:translateY(2px) rotate(-1deg)}50%{transform:translateY(-7px) rotate(1.5deg)}}@keyframes halo{50%{transform:scale(1.17);opacity:.6}}@keyframes floor{50%{transform:scale(.72);opacity:.6}}@keyframes mote{0%,100%{transform:translateY(3px);opacity:.15}50%{transform:translateY(-9px);opacity:.8}}@keyframes beacon{50%{opacity:.35;transform:scale(.65)}}@keyframes greet{0%,100%{transform:rotate(0) scale(1)}25%{transform:translateY(-9px) rotate(-9deg) scale(1.06)}53%{transform:translateY(-3px) rotate(8deg) scale(1.03)}75%{transform:rotate(-4deg)}}@media(prefers-reduced-motion:reduce){.stage *{animation:none!important;transition:none!important}.follow{transform:none!important}}
</style>
